INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261114-0001', '2026-11-14', 'memini-author', 'foundation', 'Seed: first public snapshot (ADR-0002 decision 1). Built from the private repository at public-hygiene cf20c3e (on main 804fae9, which includes infra afb2b49) plus security-md 20ac9b1; features and bugs carry over as the baseline; private history, reviews and the merge checklist stay private', NULL, NULL, NULL, NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261114-0002', '2026-11-14', 'Claude/devops-498d4ec2', 'foundation', 'CI works on the public repo''s first commit and audits the right range: check_ledgers compares a true root commit against an empty ledger (shallow still fails, B-007) and takes --base; tools/ci/audit_range.py picks the base per event; ci.yml checks out the PR head; review gate on pull_request only until T-059 (temporary)', NULL, 'B-foundation-021', NULL, NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261114-0003', '2026-11-14', 'Claude/devops-498d4ec2', 'foundation', 'commit identity gate: author and committer emails must be on the public allow list tools/ci/commit-identities.txt (memini-author@example.invalid); pre-commit --pending and CI over the audit range; refused emails never printed; repo-local neutral identity set', NULL, NULL, NULL, NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261114-0004', '2026-11-14', 'Claude/devops-498d4ec2', 'foundation', 'export allow list: the neutral commit identity and the identity-gate test''s stand-in address are public on purpose', NULL, NULL, NULL, NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261114-0005', '2026-11-14', 'Claude/devops-498d4ec2', 'foundation', 'review of fix/ci-first-commit (devops-infra): audits fail closed on an empty, unknown or unrelated base (F1); no ref input on checkout (any ref makes it fetch from github.com, also under act); a separate step selects the PR head on pull requests (F2); identity gate checks author/committer names via tools/ci/commit-names.txt in hook and CI (F3)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261114-0006', '2026-11-14', 'Claude/devops-498d4ec2', 'foundation', 'test_wheel_install installs without --offline: offline resolution needs index metadata that uv sync --frozen never caches, so it failed on every clean machine (Tier 1, test setup was wrong; every test id survives)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0101', '2026-11-15', 'Claude/vprnd-8b35793b', 'foundation', 'module feature flags: memini.infra.flags with one env flag per unshipped engine module, OFF by default, read at call time (owner decision 2026-11-14; replaces the OpenFeature plan)', 'F-foundation-023', NULL, NULL, NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0105', '2026-11-15', 'Claude/vprnd-8b35793b', 'foundation', 'flags review fixes: MEMINI_ENABLE_DOCUMENT_AUTHORITY follows the MEMINI_ENABLE_<MODULE> pattern; a non-parametrized all-off test and a test that every public function is a listed flag are linked in the ledger; src/memini/infra/flags.py is a protected check file so a default can only be flipped with the owner''s approval', 'F-foundation-023', NULL, NULL, NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0106', '2026-11-15', 'shuraD', 'foundation', 'every new commit is the owner''s: the owner''s GitHub noreply address and login join the commit identity, name and export allow lists', NULL, NULL, NULL, NULL, 'owner 2026-11-15');
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0001', '2026-11-15', 'Claude/orchestrator', 'orchestrator', 'Deterministic atomic-slice orchestrator (owner 2026-11-14, scope relayed by vp-rnd): python -m tools.orchestrator run/run-queue/check-spec/status/release; one-shot QA, coder and audit agents, path-based anti-cheat gate, sealed tests, host-side hold-out, ci.yml gates per env profile in fresh checkouts, one squash commit on main', 'F-orchestrator-001,F-orchestrator-002,F-orchestrator-003,F-orchestrator-004,F-orchestrator-005,F-orchestrator-006,F-orchestrator-007,F-orchestrator-008,F-orchestrator-009,F-orchestrator-010,F-orchestrator-011', NULL, 'pre-commit hook; pytest_gate full suite 1250 passed, coverage 92%; lint-imports, bandit, deptry, export gate', NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0102', '2026-11-15', 'Claude/vprnd-8b35793b', 'orchestrator', 'orchestrator config: the CI Security (bandit, pip-audit) and Dependencies (deptry) steps are slice and merge gates; only Claude codes until the microVM executor exists, because other engines load no guard hook and could read the hold-out directory', NULL, NULL, NULL, NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0103', '2026-11-15', 'Claude/vprnd-8b35793b', 'orchestrator', 'correction of C-20261115-0102: coder_engine is left empty (it falls back to the default engine, Claude) because a pinned engine breaks configs that define other engines, such as the test fixtures; a config note keeps the coder on Claude until the microVM executor exists', NULL, NULL, NULL, NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0104', '2026-11-15', 'Claude/vprnd-8b35793b', 'foundation', 'AGENTS.md: owner rule for new dependencies: accepted without the owner when the first PyPI release is at least 2 years old, pip-audit finds no known vulnerability in it or its dependencies, and its licence is OSI-approved and AGPL-compatible; otherwise a Tier 2 owner question; orchestrated coders request dependencies via FOLLOW-UP', NULL, NULL, NULL, NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0002', '2026-11-15', 'Claude/orchestrator', 'orchestrator', 'Orchestrator review fixes (review of 2cdeb78, MERGE: no): B1 QA and hold-out tests through tools/ci/pytest_gate; B2 guard blocks ancestor paths, glob prefixes and Bash args outside the worktree; B3 allow-listed env, names and test ids only in retry prompts, protected files watched after every run (restore + tier-2 inbox alert); B4 every audit verdict must pass; B5 QA and audit default to Claude; S1-S6, N1-N5; a dirty main worktree blocks the merge', 'F-orchestrator-001,F-orchestrator-002,F-orchestrator-003,F-orchestrator-004,F-orchestrator-005,F-orchestrator-007,F-orchestrator-008,F-orchestrator-009,F-orchestrator-011', NULL, 'pre-commit hook; pytest_gate full suite', NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0003', '2026-11-15', 'Claude/orchestrator', 'foundation', 'AGENTS.md item 7: an established dependency has a first PyPI release at least 1 year old (was 2); owner correction relayed by vp-rnd 2026-11-15: "it can be 1 year"', NULL, NULL, NULL, NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0004', '2026-11-15', 'Claude/orchestrator', 'orchestrator', 'Orchestrator second-review fixes (MERGE: no): deny-pattern scan of the coder''s added lines against in-process result forging (open bug B-foundation-022 for tools/ci/pytest_gate.py); the audited commit is the merged one and refs are watched; only safe known test ids in retry prompts; an oversized diff is rejected; non-Claude coders refused while local; anti-cheat before a dispute; one run at a time; private pytest gate copy and HOME; AGENTS.md item 7 names no licence gate (planned F-foundation-030)', 'F-orchestrator-001,F-orchestrator-002,F-orchestrator-004,F-orchestrator-006,F-orchestrator-008,F-orchestrator-011,F-foundation-030', 'B-foundation-022', 'pre-commit hook; pytest_gate full suite', NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0005', '2026-11-15', 'Claude/orchestrator', 'orchestrator', 'Orchestrator round 3 (re-check MERGE: no): AST check of the coder''s changed Python files (literal-only getattr family, dunder allow-list, forbidden calls and names, import allow-list from config + memini + declared dependencies; owner-only OVERRIDE-AST inbox line), regex scan kept as an extra layer; GIT_NO_REPLACE_OBJECTS=1 in every git env and all refs watched via for-each-ref; retry ids must equal AST node ids; release takes the run lock', 'F-orchestrator-002,F-orchestrator-006', NULL, 'pre-commit hook; pytest_gate full suite', NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0006', '2026-11-15', 'Claude/orchestrator', 'orchestrator', 'Docker executor MVP (owner 2026-11-15: the real fix is the microVM, minimal MVP): every run of coder-written code (the coder''s sandbox-pytest wrapper, gates, QA tests, hold-out) goes into a fresh docker run --rm container with --network none, an allow-listed environment, no host/.git mount and a per-run tmpfs /slice; image built from the repo uv.lock and tagged by its hash; executor defaults to docker when available, local kept for tests; non-Claude coders still refused; integration tests deselected in the sandbox and reported, not hidden; the squash-commit identity is configurable and defaults to the repo git user.name/user.email (owner 2026-11-15), and no Co-Authored-By line is ever added', 'F-orchestrator-012', NULL, 'pre-commit hook; pytest_gate full suite; opt-in real-docker smoke passed', NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0107', '2026-11-15', 'shuraD', 'foundation', 'the identity allow-list test accepts GitHub noreply addresses beside the neutral identity (owner: every new commit is the owner''s); personal emails stay refused', NULL, NULL, NULL, NULL, 'owner 2026-11-15');
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0108', '2026-11-15', 'shuraD', 'foundation', 'the commit-name list test accepts the GitHub login of a listed noreply address beside the neutral name; personal names stay refused', NULL, NULL, NULL, NULL, 'owner 2026-11-15');
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0109', '2026-11-15', 'shuraD', 'foundation', 'every GitHub Action is pinned to a full commit SHA and the runner to ubuntu-24.04 (repository setting refused tags); the docker pytest marker is registered', NULL, NULL, NULL, NULL, 'owner 2026-11-15');
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0110', '2026-11-15', 'shuraD', 'foundation', 'the orchestrator config loads without a git identity (a fresh CI runner has none); a task without one is refused before dispatch', NULL, NULL, NULL, NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0111', '2026-11-15', 'shuraD', 'foundation', 'security: CI actions on their newest Node 24 versions (checkout v7.0.1 without persisted credentials, setup-uv v7.6.0), uv pinned to 0.13.6 in CI and the sandbox image, uv >= 0.13.4 required everywhere, act maps ubuntu-24.04', NULL, NULL, NULL, NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0112', '2026-11-15', 'shuraD', 'foundation', 'orchestrator: only coder code runs in the docker sandbox with container paths; agents, setup and static/git gates on the host; per-slice tests gate = sanity+unit with src coverage', NULL, NULL, NULL, NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0113', '2026-11-15', 'shuraD', 'foundation', 'orchestrator pilot fixes: hold-out copied once per profile, agent prompts name the allowed commands, agent cost recorded from JSON output, bandit marker on container paths', NULL, NULL, NULL, NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0114', '2026-11-15', 'Claude', 'src/memini/infra/llm_providers/', 'LP-01: Define the public value types and the error that names every reason when (orchestrator slice; engines qa=claude, coder=claude, audit=claude)', 'F-src/memini/infra/llm_providers/-001', NULL, 'orchestrator: QA tests per env profile, hold-out, CI gates, diff audit', NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0115', '2026-11-15', 'shuraD', 'foundation', 'orchestrator: parallel slice runs (run slots, per-run tamper watch, run-queue --workers N; a failure holds back only its dependents)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0116', '2026-11-15', 'shuraD', 'foundation', 'orchestrator: QA test files are linted before they are sealed; one QA retry, then reject before any coder runs', NULL, NULL, NULL, NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0117', '2026-11-15', 'shuraD', 'foundation', 'orchestrator run-queue: a slice whose hold-out is not written yet waits (not started, not recorded) instead of being rejected', NULL, NULL, NULL, NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0118', '2026-11-15', 'shuraD', 'foundation', 'orchestrator run-queue: each parallel run is its own worker (<worker>-<task>), so the one-task-per-worker rule no longer refuses parallel slices', NULL, NULL, NULL, NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0119', '2026-11-15', 'shuraD', 'foundation', 'orchestrator QA prompt: never replace interpreter-wide state (os.environ etc.); record calls with monkeypatch around the call under test', NULL, NULL, NULL, NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0120', '2026-11-15', 'Claude', 'src/memini/infra/llm_providers/', 'LP-03: Map an HTTP status, headers, body text or exception to one action: rest, (orchestrator slice; engines qa=claude, coder=claude, audit=claude)', 'F-src/memini/infra/llm_providers/-002', NULL, 'orchestrator: QA tests per env profile, hold-out, CI gates, diff audit', NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0121', '2026-11-15', 'shuraD', 'foundation', 'orchestrator AST policy: allow sqlite3, threading, contextvars, queue, types, concurrent.futures, urllib.request/error, http.client, email.utils and __slots__; forbid their process, code-object, frame and thread-hook corners and sqlite extension loading', NULL, NULL, NULL, NULL, 'owner 2026-11-15: agree for AST list');
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0122', '2026-11-15', 'Claude', 'src/memini/infra/llm_providers/', 'LP-02: Parse the providers config mapping into immutable settings and resolve r (orchestrator slice; engines qa=claude, coder=claude, audit=claude)', 'F-src/memini/infra/llm_providers/-003', NULL, 'orchestrator: QA tests per env profile, hold-out, CI gates, diff audit', NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0123', '2026-11-15', 'Claude', 'src/memini/infra/llm_providers/', 'LP-10: Limit simultaneous calls to a provider (max_concurrent from config) acro (orchestrator slice; engines qa=claude, coder=claude, audit=claude)', 'F-src/memini/infra/llm_providers/-004', NULL, 'orchestrator: QA tests per env profile, hold-out, CI gates, diff audit', NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0124', '2026-11-15', 'shuraD', 'foundation', 'ruff isort: memini is always first-party, so QA lint of tests importing a not-yet-written module matches the gate lint after the coder writes it (LP-04, LP-08)', NULL, NULL, NULL, NULL, 'owner 2026-11-15: approve');
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0125', '2026-11-15', 'Claude', 'src/memini/infra/llm_providers/', 'LP-04: Build the chat-completions request for kind openai_compatible and parse  (orchestrator slice; engines qa=claude, coder=claude, audit=claude)', 'F-src/memini/infra/llm_providers/-005', NULL, 'orchestrator: QA tests per env profile, hold-out, CI gates, diff audit', NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0126', '2026-11-15', 'Claude', 'src/memini/infra/llm_providers/', 'LP-08: Open the one shared SQLite file safely for many threads and processes, c (orchestrator slice; engines qa=claude, coder=claude, audit=claude)', 'F-src/memini/infra/llm_providers/-006', NULL, 'orchestrator: QA tests per env profile, hold-out, CI gates, diff audit', NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0127', '2026-11-15', 'Claude', 'src/memini/infra/llm_providers/', 'LP-09: Record that a provider is exhausted or resting until a time, in the shar (orchestrator slice; engines qa=claude, coder=claude, audit=claude)', 'F-src/memini/infra/llm_providers/-007', NULL, 'orchestrator: QA tests per env profile, hold-out, CI gates, diff audit', NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0128', '2026-11-15', 'Claude', 'src/memini/infra/llm_providers/', 'LP-11: Count calls and tokens per role, per question and per run in the shared  (orchestrator slice; engines qa=claude, coder=claude, audit=claude)', 'F-src/memini/infra/llm_providers/-008', NULL, 'orchestrator: QA tests per env profile, hold-out, CI gates, diff audit', NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0129', '2026-11-15', 'shuraD', 'foundation', 'orchestrator stage chain: configurable stages before code, each with its own queue, records and loop (run-queue --stage/--all); the spec stage writes spec + hidden tests per task line and hands the task to code', NULL, NULL, NULL, NULL, 'owner 2026-11-15: two queues, more than 2, go for it');
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0130', '2026-11-15', 'shuraD', 'foundation', 'orchestrator: QA and spec-stage tests pass every merge gate check (gitleaks per file) before sealing; a silent check failure counts; prompts ask for obvious fake secrets', NULL, NULL, NULL, NULL, 'owner 2026-11-15: we need this one');
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0131', '2026-11-15', 'shuraD', 'foundation', 'AGENTS.md: no full test runs while fixing; affected tests only; the full suite runs once at the end, when everything is merged', NULL, NULL, NULL, NULL, 'owner 2026-11-15: it should be in the rule file');
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0132', '2026-11-15', 'shuraD', 'foundation', 'AST check: allow exactly object.__setattr__(self, "<name>", value) in a class-body method (frozen dataclass idiom); every other __setattr__ use stays refused', NULL, NULL, NULL, NULL, 'owner 2026-11-15: approve B');
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0133', '2026-11-15', 'shuraD', 'foundation', 'orchestrator: a failed lint/type/security gate gives the coder <rule> <path>:<line> for findings in its own paths, never the message text', NULL, NULL, NULL, NULL, 'owner 2026-11-15: option 2, fix #2');
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0134', '2026-11-15', 'Claude', 'src/memini/infra/llm_providers/', 'LP-05: Build and parse the generation requests for kinds gemini and ollama, wit (orchestrator slice; engines qa=claude, coder=claude, audit=claude)', 'F-src/memini/infra/llm_providers/-009', NULL, 'orchestrator: QA tests per env profile, hold-out, CI gates, diff audit', NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0135', '2026-11-15', 'shuraD', 'foundation', 'dependency: neo4j==6.4.1 (graph-schema driver; pulls pytz); 0 OSV advisories for both, current maintained line', NULL, NULL, NULL, NULL, 'owner 2026-11-15: go with 6.4.1');
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0136', '2026-11-15', 'shuraD', 'foundation', 'orchestrator coder prompt: names the deny-scan regexes and bandit nosec syntax before the first attempt', NULL, NULL, NULL, NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0137', '2026-11-15', 'shuraD', 'foundation', 'orchestrator dev squads: one coding queue per work unit (code_queues, run-queue --queue <unit>); spec stage routes by module; dependencies across squads; max_parallel 8', NULL, NULL, NULL, NULL, 'owner 2026-11-15: dev squads');
