INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0139', '2026-11-15', 'Claude', 'src/memini/infra/llm_providers/', 'LP-17: Store one row per real call, per cache hit and per embedding batch in th (orchestrator slice; engines qa=claude, coder=claude, audit=claude)', 'F-src/memini/infra/llm_providers/-010', NULL, 'orchestrator: QA tests per env profile, hold-out, CI gates, diff audit', NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0140', '2026-11-15', 'Claude', 'src/memini/core/graph/', 'GS-05: Define the shared value types, errors and protocols of the graph query l (orchestrator slice; engines qa=claude, coder=claude, audit=claude)', 'F-src/memini/core/graph/-001', NULL, 'orchestrator: QA tests per env profile, hold-out, CI gates, diff audit', NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0141', '2026-11-15', 'Claude', 'src/memini/infra/graph/', 'GS-13: Decide whether a database URI may be used, accepting local hosts and exp (orchestrator slice; engines qa=claude, coder=claude, audit=claude)', 'F-src/memini/infra/graph/-001', NULL, 'orchestrator: QA tests per env profile, hold-out, CI gates, diff audit', NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0142', '2026-11-15', 'Claude', 'src/memini/infra/llm_providers/', 'LP-06: Send an HttpRequest over stdlib urllib and return the status, headers an (orchestrator slice; engines qa=claude, coder=claude, audit=claude)', 'F-src/memini/infra/llm_providers/-011', NULL, 'orchestrator: QA tests per env profile, hold-out, CI gates, diff audit', NULL, NULL);
